import{_ as t,o,c as r,aa as s}from"./chunks/framework.BAs_AphD.js";const i="/buildary-help-preview/media/cs/performedworks/chybova_zprava1.png",n="/buildary-help-preview/media/cs/performedworks/kompetence1.png",a="/buildary-help-preview/media/cs/performedworks/kompetencni-okruhy2.png",l="/buildary-help-preview/media/cs/performedworks/oznameni-spp.png",b=JSON.parse('{"title":"Setting Permissions","description":"","frontmatter":{"title":"Setting Permissions","wiki":"en:performedworks:competences"},"headers":[],"relativePath":"en/performedworks/competences.md","filePath":"en/performedworks/competences.md","lastUpdated":1794388980000}'),p={name:"en/performedworks/competences.md"};function c(h,e,m,d,u,g){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="setting-permissions" tabindex="-1">Setting Permissions <a class="header-anchor" href="#setting-permissions" aria-label="Permalink to &quot;Setting Permissions&quot;">​</a></h1><p>Before starting work in the Performed Works module, users must be assigned the correct roles and linked to the appropriate companies.</p><p>If this step is skipped or performed incorrectly, the user will not be able to work in the module and may see the following message:</p><img src="'+i+'" alt="" width="600" loading="lazy"><p><em>The settings must be configured by an Administrator or a user who has the appropriate permissions for Project Administration.</em></p><p>Correct permission settings require assigning the user to the correct company and assigning them the appropriate role on the project.</p><h3 id="assigning-an-organization" tabindex="-1">Assigning an Organization <a class="header-anchor" href="#assigning-an-organization" aria-label="Permalink to &quot;Assigning an Organization&quot;">​</a></h3><p>In the &quot;Project Team&quot; under the &quot;Project Team Members&quot; tab, add a new user or edit an existing one. In the Company field, select the appropriate company.</p><img src="'+n+'" alt="" width="400" loading="lazy"><p><em>Although this is not common, a user can be assigned to multiple companies. This can be useful if the user needs to work on behalf of additional project participants. For example, if a site manager needs to enter Performed Works on behalf of some subcontractors, these companies must also be assigned to the user.</em></p><h3 id="assigning-a-role" tabindex="-1">Assigning a Role <a class="header-anchor" href="#assigning-a-role" aria-label="Permalink to &quot;Assigning a Role&quot;">​</a></h3><p>In the Edit Team Member window, select the role the user performs on the project in the &quot;Default Role ...&quot; field. The role also determines the user&#39;s permissions, meaning the functions they can perform. The default permission settings are described below. If these do not meet the requirements, they can be modified.</p><h3 id="setting-permissions-by-role" tabindex="-1">Setting Permissions by Role <a class="header-anchor" href="#setting-permissions-by-role" aria-label="Permalink to &quot;Setting Permissions by Role&quot;">​</a></h3><p>The Member Roles tab contains all roles available for the given project. Roles that have permission to work in the Performed Works module by default are shown in the following image, including their default permission settings.</p><h3 id="setting-permissions-by-role-1" tabindex="-1">Setting Permissions by Role <a class="header-anchor" href="#setting-permissions-by-role-1" aria-label="Permalink to &quot;Setting Permissions by Role&quot;">​</a></h3><ul><li><p><strong>Contractor SPP Entry –</strong> allows the user to enter the Proposed Quantity and price of items in the Contractor Works process. During the approval process, the user can then enter the Changed Quantity of items. The user can subsequently submit the Measurement Report for approval by the Technical Supervisor or the Client Representative.</p></li><li><p><strong>Contractor SPP Approval –</strong> allows the user to change the status of items, i.e. approve or reject the contractor&#39;s proposals, and modify the Invoiced Quantity and price in the Contractor Works process. The user can also completely delete the work statements in the given Measurement Report. A user with this permission can approve the Measurement Report or return it to the Contractor Representative for correction. They can also unlock a closed Measurement Report.</p></li><li><p><strong>Subcontractor SPP Entry –</strong> allows the user to enter the Proposed Quantity and price of items in the Subcontractor Works process. During the approval process, the user can then enter the Changed Quantity of items. The user can subsequently submit the Measurement Report for approval by the Contractor Representative.</p></li><li><p><strong>Subcontractor SPP Approval –</strong> allows the user to change the status of items, i.e. approve or reject the subcontractor&#39;s proposals, and modify the Invoiced Quantity and price in the Subcontractor Works process. A user with this permission can approve the Measurement Report or return it to the Subcontractor Representative for correction.</p></li></ul><img src="'+a+'" alt="" width="600" loading="lazy"> In typical situations on construction projects, the default role settings should be sufficient. However, the Project Administrator can modify the role settings as needed or create entirely new roles. <div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>If, for example, a site manager wants to enter Performed Works on behalf of one of the subcontractors, their role must also include the Subcontractor SPP Entry permission.</strong></p></div><h2 id="email-notifications" tabindex="-1">Email Notifications <a class="header-anchor" href="#email-notifications" aria-label="Permalink to &quot;Email Notifications&quot;">​</a></h2><figure class="shot" style="--w:600px;"><img src="'+l+'" alt="Notification settings for a project team member." width="500" loading="lazy"></figure><p>For each project team member, you can individually configure whether they should receive notifications by email. The options shown in the image are available:</p><p><strong>None</strong> - no email will ever be sent.</p><p><strong>HTML Email</strong> - the message will be sent automatically by email.</p>',24)])])}const y=t(p,[["render",c]]);export{b as __pageData,y as default};
